<?php  use App\Models\User; use Illuminate\Support\Facades\Hash;  test('password can be updated', function () {     $user = User::factory()->create([         'password' => Hash::make('old-password123'),     ]);      $response = $this         ->actingAs($user)         ->from(route('profile.edit'))         ->put(route('password.update'), [             'current_password' => 'old-password123',             'password' => 'new-password123',             'password_confirmation' => 'new-password123',         ]);      $response->assertSessionHasNoErrors();     $response->assertRedirect(route('profile.edit'));     $response->assertSessionHas('status', 'password-updated');      $this->assertTrue(Hash::check('new-password123', $user->fresh()->password)); });  test('correct password must be provided to update password', function () {     $user = User::factory()->create([         'password' => Hash::make('old-password123'),     ]);      $response = $this         ->actingAs($user)         ->from(route('profile.edit'))         ->put(route('password.update'), [             'current_password' => 'wrong-password',             'password' => 'new-password123',             'password_confirmation' => 'new-password123',         ]);      $response->assertSessionHasErrorsIn('updatePassword', 'current_password');     $response->assertRedirect(route('profile.edit'));      $this->assertTrue(Hash::check('old-password123', $user->fresh()->password)); });